# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SUYUN POLAR YAPISI, HİDROJEN BAĞLARI VE BİYOLOJİK ÖNEMİ</text>\n  <rect x="20" y="45" width="290" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="165" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">SU MOLEKÜLLERİ ARASI HİDROJEN BAĞI</text>\n  <circle cx="115" cy="120" r="22" fill="#ef4444" stroke="#991b1b" stroke-width="2"/>\n  <text x="115" y="125" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">O (δ-)</text>\n  <circle cx="80" cy="155" r="13" fill="#3b82f6" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="80" y="159" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">H+</text>\n  <circle cx="150" cy="155" r="13" fill="#3b82f6" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="150" y="159" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">H+</text>\n  <line x1="100" y1="135" x2="88" y2="146" stroke="#0f172a" stroke-width="2.5"/>\n  <line x1="130" y1="135" x2="142" y2="146" stroke="#0f172a" stroke-width="2.5"/>\n  <circle cx="225" cy="155" r="22" fill="#ef4444" stroke="#991b1b" stroke-width="2"/>\n  <text x="225" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">O (δ-)</text>\n  <circle cx="255" cy="118" r="13" fill="#3b82f6" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="255" y="122" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">H+</text>\n  <circle cx="255" cy="190" r="13" fill="#3b82f6" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="255" y="194" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">H+</text>\n  <line x1="238" y1="138" x2="248" y2="128" stroke="#0f172a" stroke-width="2.5"/>\n  <line x1="238" y1="172" x2="248" y2="182" stroke="#0f172a" stroke-width="2.5"/>\n  <line x1="163" y1="155" x2="203" y2="155" stroke="#16a34a" stroke-width="3" stroke-dasharray="5,4"/>\n  <text x="165" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Kesikli Çizgi: Zayıf Hidrojen Bağı (Kohezyon)</text>\n  <text x="165" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Düz Çizgi: Polar Kovalent Bağ (Molekül İçi)</text>\n  <rect x="325" y="45" width="355" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="502" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">SUYUN TEMEL ÖZELLİKLERİ VE CANLILAR İÇİN ÖNEMİ</text>\n  <text x="340" y="92" font-size="11" font-weight="bold" fill="#14532d">• Kohezyon ve Adhezyon: Kökten yapraklara su taşınması</text>\n  <text x="340" y="114" font-size="11" font-weight="bold" fill="#14532d">• Yüzey Gerilimi: Su üstünde böceklerin yürüyebilmesi</text>\n  <text x="340" y="136" font-size="11" font-weight="bold" fill="#14532d">• Yüksek Öz Isı: İklimlerin ve vücut ısısının dengelenmesi</text>\n  <text x="340" y="158" font-size="11" font-weight="bold" fill="#14532d">• Buharlaşma Isısı: Terleme ile vücudun soğutulması</text>\n  <text x="340" y="180" font-size="11" font-weight="bold" fill="#14532d">• Buzun Yoğunluğu: Su yüzeyden donar, alt yaşam korunur</text>\n  <text x="340" y="202" font-size="11" font-weight="bold" fill="#14532d">• Çözücülük: Madde taşınması, boşaltım ve enzim etkinliği</text>\n  <text x="340" y="224" font-size="10.5" font-weight="bold" fill="#b91c1c">Not: Enzimlerin çalışması için ortamda en az %15 su şarttır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ASİTLER, BAZLAR, pH ÖLÇEĞİ (0 - 14) VE HOMEOSTAZİ</text>\n  <rect x="40" y="55" width="200" height="42" fill="#fecaca" stroke="#dc2626" stroke-width="2"/>\n  <rect x="240" y="55" width="220" height="42" fill="#bbf7d0" stroke="#16a34a" stroke-width="2"/>\n  <rect x="460" y="55" width="200" height="42" fill="#bfdbfe" stroke="#2563eb" stroke-width="2"/>\n  <text x="140" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">ASİDİK (pH: 0 - 7 arası)</text>\n  <text x="350" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">NÖTR (pH = 7,0)</text>\n  <text x="560" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">BAZİK (pH: 7 - 14 arası)</text>\n  <text x="45" y="115" font-size="11" font-weight="bold" fill="#b91c1c">0 ← Asitlik Artar (H+ &gt; OH-)</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Saf Su (H+ = OH-)</text>\n  <text x="655" y="115" text-anchor="end" font-size="11" font-weight="bold" fill="#1d4ed8">Bazlık Artar (OH- &gt; H+) → 14</text>\n  <rect x="25" y="132" width="315" height="110" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="182" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">ASİTLERİN ÖZELLİKLERİ VE ÖRNEKLER</text>\n  <text x="38" y="172" font-size="10.5" fill="#881337">• Sulu çözeltilerine H+ (hidrojen/hidronyum) iyonu verir.</text>\n  <text x="38" y="190" font-size="10.5" fill="#881337">• Tatları ekşidir, mavi turnusol kâğıdını kırmızıya çevirir.</text>\n  <text x="38" y="208" font-size="10.5" fill="#881337">• Mide öz suyu (~1,5), limon (~2), kahve (~5), süt (~6,5).</text>\n  <text x="38" y="226" font-size="10.5" font-weight="bold" fill="#881337">• CO2, laktik asit, yağ asidi ve amino asit pH değerini düşürür.</text>\n  <rect x="360" y="132" width="315" height="110" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="517" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">BAZLAR, TUZLAR VE TAMPON ÇÖZELTİLER</text>\n  <text x="373" y="172" font-size="10.5" fill="#1e3a8a">• Bazlar suya OH- verir, acıdır, kırmızı turnusolu mavi yapar.</text>\n  <text x="373" y="190" font-size="10.5" fill="#1e3a8a">• İnsan kanı (~7,4), deniz suyu (~8), sabunlu su, amonyak (NH3).</text>\n  <text x="373" y="208" font-size="10.5" fill="#1e3a8a">• Asit + Baz → Tuz + Su (Nötralleşme tepkimesi).</text>\n  <text x="373" y="226" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Tampon çözeltiler (bikarbonat) kan pH değerini 7,4\'te korur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CANLILAR İÇİN ÖNEMLİ MİNERALLER VE BİYOLOJİK GÖREVLERİ</text>\n  <rect x="20" y="45" width="210" height="95" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.8"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Kalsiyum (Ca) ve Fosfor (P)</text>\n  <text x="30" y="88" font-size="10.5" fill="#1e3a8a">• Kemik ve dişlerin sertleşmesi</text>\n  <text x="30" y="106" font-size="10.5" fill="#1e3a8a">• Ca: Kas kasılması, kan pıhtılaşması</text>\n  <text x="30" y="124" font-size="10.5" fill="#1e3a8a">• P: DNA, RNA, ATP ve hücre zarı</text>\n  <rect x="245" y="45" width="210" height="95" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.8"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">Demir (Fe) ve İyot (I)</text>\n  <text x="255" y="88" font-size="10.5" fill="#7f1d1d">• Fe: Alyuvardaki hemoglobin yapısı</text>\n  <text x="255" y="106" font-size="10.5" fill="#7f1d1d">• Fe eksikliği: Anemi (kansızlık)</text>\n  <text x="255" y="124" font-size="10.5" fill="#7f1d1d">• I: Tiroksin hormonu (Eksikliği: Guatr)</text>\n  <rect x="470" y="45" width="210" height="95" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.8"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Magnezyum (Mg)</text>\n  <text x="480" y="88" font-size="10.5" fill="#14532d">• Bitkide klorofil pigmentinin merkezi</text>\n  <text x="480" y="106" font-size="10.5" fill="#14532d">• İnsanda kemik, kas ve sinir işlevi</text>\n  <text x="480" y="124" font-size="10.5" fill="#14532d">• Birçok enzimin kofaktörü (yardımcısı)</text>\n  <rect x="20" y="152" width="325" height="92" rx="8" fill="#fffbeb" stroke="#f59e0b" stroke-width="1.8"/>\n  <text x="182" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">Sodyum (Na), Potasyum (K) ve Klor (Cl)</text>\n  <text x="32" y="194" font-size="10.5" fill="#78350f">• Hücre içi ve dışı su-tuz (ozmotik basınç) dengesi</text>\n  <text x="32" y="212" font-size="10.5" fill="#78350f">• Sinir hücrelerinde uyartı (impuls) iletimi</text>\n  <text x="32" y="230" font-size="10.5" fill="#78350f">• Cl: Midede hidroklorik asit (HCl) üretimi</text>\n  <rect x="355" y="152" width="325" height="92" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.8"/>\n  <text x="517" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">MİNERALLERİN GENEL ÖZELLİKLERİ</text>\n  <text x="367" y="194" font-size="10.5" fill="#581c87">• Canlılar tarafından sentezlenemez, dışarıdan hazır alınır.</text>\n  <text x="367" y="212" font-size="10.5" fill="#581c87">• Sindirilmeden hücre zarından geçer, enerji (ATP) vermez.</text>\n  <text x="367" y="230" font-size="10.5" fill="#581c87">• Yapıya katılır ve kofaktör olarak düzenleyici görev yapar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
